import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
// Keep the existing authenticated applications and their asset URLs intact.
// New public routes are generated by Astro. blog/private is linked from the signed-in portal, so it is
// carried over unchanged, exactly as the previous site served it.
for (const path of [
  "assets",
  "login",
  "portal",
  "app",
  "AI",
  "music-generator",
  "moments",
  "links",
  "blog/images",
  "blog/private",
  "blog/post/earth-school",
  "projects/images",
  "style.css",
]) {
  if (existsSync(path)) cpSync(path, `dist/${path}`, { recursive: true });
}
const sitemap = [
  "/",
  "/vision/",
  "/projects/",
  "/videos/",
  "/blog/",
  "/photography/",
  "/about-me/",
  "/contact/",
  "/updates/",
  ...JSON.parse(readFileSync("src/data/posts.json", "utf8")).map((p) => p.url),
];
writeFileSync(
  "dist/sitemap.xml",
  `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${sitemap.map((path) => `<url><loc>https://www.quentinnichols.com${path}</loc></url>`).join("")}</urlset>`,
);
writeFileSync(
  "dist/robots.txt",
  "User-agent: *\nAllow: /\nDisallow: /portal/\nDisallow: /app/\nDisallow: /AI/\nDisallow: /login/\nSitemap: https://www.quentinnichols.com/sitemap.xml\n",
);
